/* prog17_whitespace_trim.c
 * Reimplementation of the original binary's behaviour:
 *   * read the first command‑line argument,
 *   * limit it to 1024 characters,
 *   * trim leading and trailing whitespace,
 *   * collapse each internal run of whitespace to a single space,
 *   * print the result, or "EMPTY" if the result is empty.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_INPUT 1024          /* maximum characters to process */
#define OUT_BUF   (MAX_INPUT + 1)   /* output buffer (including terminating NUL) */

int main(int argc, char *argv[])
{
    const char *src;
    char out[OUT_BUF];
    size_t out_len = 0;
    size_t i, n;

    /* No argument → print EMPTY */
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }

    src = argv[1];
    n = strlen(src);
    if (n > MAX_INPUT)               /* limit to 1024 characters */
        n = MAX_INPUT;

    /* Skip leading whitespace */
    i = 0;
    while (i < n && isspace((unsigned char)src[i]))
        ++i;

    /* Process the rest of the string */
    while (i < n) {
        if (isspace((unsigned char)src[i])) {
            /* Emit a single space only if we have already output something */
            if (out_len > 0) {
                out[out_len++] = ' ';
            }
            /* Skip the whole run of whitespace */
            while (i < n && isspace((unsigned char)src[i]))
                ++i;
        } else {
            out[out_len++] = src[i++];
        }
    }

    /* Remove a trailing space that may have been added */
    if (out_len > 0 && out[out_len - 1] == ' ')
        --out_len;

    out[out_len] = '\0';

    if (out_len == 0)
        puts("EMPTY");
    else
        puts(out);

    return 0;
}
